      "n_min": 1,
      "n_max": 100000,
      "value_min": -10000,
      "value_max": 10000,
      "time_limit": "O(n)",
      "space_limit": "O(1) extra"
    },
    "examples": [
      {
        "input": "inventory = [4, 7, 2, 9, 1, 5]",
